entries[87208] = { ["name"] = "Siegel der Macht", ["text"] = "Wird beim Aufheben gebunden\n\"Ein uraltes Symbol der Stärke aus der Geschichte Pandarias.\"" }
entries[87209] = { ["name"] = "Siegel der Weisheit", ["text"] = "Wird beim Aufheben gebunden\n\"Ein uraltes Symbol des Wissens aus der Geschichte Pandarias.\"" }
entries[87210] = { ["name"] = "Schimäre der Angst", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine entsetzliche, formlose Masse aus Schrecken, die Euren Geist mit Furcht erfüllt.\"" }
entries[87212] = { ["name"] = "Atem des Schwarzen Prinzen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verstärkt jegliche Sha-berührte Ausrüstung enorm. Entfernt alle vorhandenen Edelsteine und Verzauberungen.\n1 Aufladung\n\"Die Macht des letzten Schwarzdrachen steht zu Eurer Verfügung.\"" }
entries[87213] = { ["name"] = "Nebeldurchdringende Brille", ["text"] = "Wird beim Anlegen gebunden\nKopf\nAnlegen: Ermöglicht Euch, zusätzliche Erzadern und Kräutervorkommen aufzuspüren, während Ihr Euch in Pandaria befindet.\n\"Obwohl diese Brille sehr modisch ist, muss sie nicht aufgesetzt werden, um von ihrer Spezialfähigkeit zu profitieren.\"\nVerkaufspreis:" }
entries[87214] = { ["name"] = "Blingtron 4000", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Setzt den unglaublichen Blingtron 4000 zusammen, einen Roboter von unendlichem Reichtum. Bling, wie er gerne genannt wird, händigt jedem, der mit ihm spricht, ein zufälliges Geschenk aus, aber nur ein Mal pro Tag. Hält 10 Min. lang an. (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst von Pandaria (75)" }
entries[87215] = { ["name"] = "Wurmlochgenerator: Pandaria", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Teleportiert Euch an irgendeinen Ort in Pandaria. Der exakte Ort ist schwer zu bestimmen, aber er ist wahrscheinlich ziemlich weit entfernt. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst von Pandaria (1)\n\"An der Seite ist eine winzige Notiz: Huiiiiiiiiiiiiiii!\"\nVerkaufspreis:" }
entries[87216] = { ["name"] = "Thermischer Amboss", ["text"] = "Benutzen: Platziert einen thermischen Amboss zu Euren Füßen, der allen in der Nähe befindlichen Charakteren erlaubt, sowohl einen Amboss als auch eine Schmiede zu benutzen. Hält 5 Min. lang an. (5 Min Abklingzeit)\n20 Aufladungen\nVerkaufspreis:" }
