entries[87250] = { ["name"] = "Rakete mit abgereichertem Kyparium", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nEine Höhepunkt goblinischer Ingenieurskunst! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn Kyparit seine Bernsteinessenz entzogen wird, kommt es kaum noch zu Korrosion durch Raketentreibstoff.\"\nBeruf:\nIngenieurskunst" }
entries[87251] = { ["name"] = "Geosynchroner Weltendreher", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nEine Apparatur, die die Welt selbst unter Euch rotieren lässt! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Rakete wurde ursprünglich entworfen, um die Umdrehung der Welt zu beschleunigen und so die Nächte zu verkürzen. Wenn Gnome unter Schlafmangel leiden, setzen sie sich große Ziele.\"\nBeruf:\nIngenieurskunst" }
entries[87253] = { ["name"] = "Unerschöpfliches Resteessen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Richtet ein Resteessen für Eure gesamte Gruppe oder Euren gesamten Schlachtzug her.\n\nStellt im Verlauf von 20 Sek. 21682 Gesundheit und ( 5000 / 5 * 20) Mana wieder her. (30 Min Abklingzeit)\nVerkaufspreis:" }
entries[87257] = { ["name"] = "Arkaner Familiarstein", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: Familiarstein (1)\nBenutzen: Beschwört einen arkanen Familiar, der Euch folgt, und gibt ihn wieder frei. Der Familiar wird verschwinden, wenn Ihr Euch ausloggt." }
