entries[87263] = { ["name"] = "Mit Gift überzogener Kiefer", ["text"] = "Questgegenstand\n\"Das Gift tropft vom Kiefer und verätzt alles, das es berührt...\"" }
entries[87264] = { ["name"] = "Bräu der vier Sinne", ["text"] = "Benutzen: Schärft Eure Sinne und erlaubt Euch, die Last des Sehen hinter Euch zu lassen.\nVerkaufspreis:" }
entries[87265] = { ["name"] = "Tigerhandwickel", ["text"] = "Wird beim Aufheben gebunden\nHände Leder\n1 Rüstung\nHaltbarkeit 18 / 18\nVerkaufspreis:" }
entries[87266] = { ["name"] = "Rezept: Bananendurchströmter Rum", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man bananendurchströmten Rum herstellt.\n\nBananendurchströmter Rum\nBenutzen: Ein starkes alkoholisches Getränk, das Euch 30 Sek. lang glauben lässt, Ihr wärt ein Ho-zen-Pirat. (10 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Banane von Tel'Abim , Flüchtiger Rum , Hexenbeeren (200), Seidenraupenpuppe , Schwarzer Pfeffer" }
entries[87267] = { ["name"] = "Kodex des Kreuzzugs", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Foliant enthält den vollständigen Bericht der Geschichte des Scharlachroten Kreuzzugs. Außerdem enthält er Statuten, Verordnungen und Rituale sowie den kompletten Kader der Mitglieder der Organisation.\"" }
