entries[87269] = { ["name"] = "Resonanzkristall von Kypari Ik", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Kristall pulsiert vor Energie.\"" }
entries[87276] = { ["name"] = "Ausgebrannte Glyphe", ["text"] = "Klassen: Priester\n\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[87277] = { ["name"] = "Glyphe 'Val'kyr'", ["text"] = "Klassen: Priester\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Euer Effekt 'Geist der Erlösung' aktiv ist, habt Ihr nun das Erscheinungsbild einer Val'kyr.\nVerkaufspreis:" }
