entries[87768] = { ["name"] = "Zügel der Onyxwolkenschlange", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare Onyxwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Onyxwolkenschlangen sind aggressiver und waghalsiger als ihre Verwandten, die himmlischen Onyxwolkenschlangen.\"\nQuest:\nÜberraschungsangriff!\nOrt:\nTonlongsteppe" }
entries[87769] = { ["name"] = "Zügel der Purpurwolkenschlange", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare Purpurwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Purpurwolkenschlangen neigen zu Träumereien und begeben sich spontan auf scheinbar zufällige Reisen, die gelegentlich Tage andauern.\"\nErfolg:\nHeldenruhm von Pandaria\nKategorie:\nDungeons & Schlachtzüge" }
entries[87771] = { ["name"] = "Zügel der himmlischen Onyxwolkenschlange", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare himmlische Onyxwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Himmlische Onyxwolkenschlangen sind von Geburt an am ganzen Körper mit violetten Schuppen bedeckt. Mit der Zeit verdunkeln sich diese Schuppen zum Farbton von Onyx.\"\nBeute von:\nSha des Zorns\nOrt:\nKun-Lai-Gipfel" }
entries[87773] = { ["name"] = "Zügel der himmlischen Purpurwolkenschlange", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare himmlische Purpurwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Himmlische Purpurwolkenschlangen zählen zu den edelsten Drachen.\"\nErfolg:\nRuhm des Pandaria-Schlachtzüglers\nKategorie:\nDungeons & Schlachtzüge" }
entries[87774] = { ["name"] = "Zügel der himmlischen Goldwolkenschlange", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare himmlische Goldwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Kaiser Shaohao\n- Ehrfürchtig\nVerkaufspreis:\n\"Dieser großen Kreatur, die glüht wie ein Sonnenaufgang über den Bergen, entspringt Wärme und Hoffnung.\"\nVerkäufer:\nNebelwirker Ku\nZone:\nZeitlose Insel\nFraktion:\nKaiser Shaohao - Ehrfürchtig" }
entries[87775] = { ["name"] = "Yu'lei, Tochter der Jade", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Yu'lei, Tochter der Jade, und gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser großen Kreatur, die wie Mondlicht durch feinste Jade schimmert, entspringt Wärme und Weisheit.\"\nVerkäufer:\nNebelwirkerin Xia\nZone:\nZeitlose Insel\nKosten:\n5.000" }
entries[87776] = { ["name"] = "Zügel der himmlischen Azurwolkenschlange", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare himmlische Azurwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser großen Kreatur, die wie ein wolkenloser Himmel an einem Sommerabend leuchtet, entspringt Wärme und Gelassenheit.\"\nErfolg:\nHerr der Reittiere\nKategorie:\nReittiere" }
entries[87777] = { ["name"] = "Zügel der astralen Wolkenschlange", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare astrale Wolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Man geht davon aus, dass die astralen Wolkenschlangen Antworten auf einige der größten Geheimnisse des Lebens kennen. Zu dumm, dass sie nicht sprechen können.\"\nBeute von:\nBehälter aus reiner Energie" }
entries[87779] = { ["name"] = "Uralter Guo-Lai-Truhenschlüssel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Öffnet eine uralte Guo-Lai-Truhe in den Guo-Lai-Hallen." }
entries[87780] = { ["name"] = "Martars Lupe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenutzen: Beschwört Martar den Nicht-sehr-Klugen, der 10 Min. lang gemeinsam mit Euch kämpfen, Abenteuer bestreiten und herumtollen wird. (1 Stunde Abklingzeit)\nVerkaufspreis:" }
entries[87781] = { ["name"] = "Zügel des azurblauen Reitkranichs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren azurblauen Reitkranich und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Goldener Lotus\n- Ehrfürchtig\nVerkaufspreis:\n\"Der majestätische Kranich ist ein geschätzter Freund der Pandaren.\"\nVerkäufer:\nJaluu der Spendable\nZone:\nTal der Ewigen Blüten\nFraktion:\nGoldener Lotus - Ehrfürchtig\nKosten:" }
entries[87782] = { ["name"] = "Zügel des goldenen Reitkranichs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren goldenen Reitkranich und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Goldener Lotus\n- Ehrfürchtig\nVerkaufspreis:\n\"Der Kranich ist das Symbol von Weisheit und Edelmut. Seine Fähigkeit, uns in die Lüfte zu tragen, ist nichts weniger als ein Wunder. - Jaluu der Spendable\"\nVerkäufer:\nJaluu der Spendable\nZone:\nTal der Ewigen Blüten\nFraktion:\nGoldener Lotus - Ehrfürchtig\nKosten:" }
entries[87783] = { ["name"] = "Zügel des königlichen Reitkranichs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren königlichen Reitkranich und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Goldener Lotus\n- Ehrfürchtig\nVerkaufspreis:\n\"Der Kranich ist das Symbol von Weisheit und Edelmut. Seine Fähigkeit, uns in die Lüfte zu tragen, ist nichts weniger als ein Wunder. - Jaluu der Spendable\"\nVerkäufer:\nJaluu der Spendable\nZone:\nTal der Ewigen Blüten\nFraktion:\nGoldener Lotus - Ehrfürchtig\nKosten:" }
entries[87784] = { ["name"] = "Zügel des Dschungelreitkranichs", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Dschungelreitkranich und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Als geschätztes Reittier ist der Dschungelkranich im Süden Pandarias für seine Geschwindigkeit und Beweglichkeit bekannt, die das Leben auf der Flucht vor den Krasaritigern mit sich bringt.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[87785] = { ["name"] = "Zügel des Albinoreitkranichs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Albinoreitkranich und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:" }
entries[87786] = { ["name"] = "Zügel des schwarzen Reityaks", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares schwarzes Reityak oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Grummel, die nachts zum Kun-Lai-Gipfel reisen, bevorzugen diese dunkelhaarigen Yaks, damit sie nicht gesehen werden. Allerdings entfernen sie dazu erst einmal die Glocken aus deren Schmuck.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[87787] = { ["name"] = "Zügel des bescheidenen Expeditionsyaks", ["text"] = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares braunes Reityak oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Anders als seine lastentragenden Artgenossen reist dieses Yak gerne leicht und auch keine allzu langen Strecken am Stück.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
