entries[88532] = { ["name"] = "Lotuswasser", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. insgesamt ( 1375 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[88535] = { ["name"] = "Geschärfter Tuskarrspeer", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand\n1 - 2 Schaden Geschwindigkeit 2.50\n(0.6 Schaden pro Sekunde)\nHaltbarkeit 30 / 30\nBenutzen: Pflanzt den Speer in den Boden, woraufhin sich Eure Angelfertigkeit und die aller Angler innerhalb von 15 Metern um 5 erhöht. Hält 10 Min. lang an. (10 Min Abklingzeit)\nBenötigt Die Angler\n- Respektvoll\n\"Ein traditioneller Tuskarrangelspeer - die Handwerkskunst ist eine Augenweide.\"" }
entries[88538] = { ["name"] = "Sha-besessener Kristall", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Tintiger Rauch wirbelt durch das Innere.\"" }
